#[cfg(feature = "tokens")]
#[doc = "Create a bank account token"]
pub async fn create_token(
    client: &crate::Client,
    params: &crate::tokens::CreateTokenParams,
) -> Result<crate::tokens::Token, crate::Error> {
    let path = crate::params::format_path("/v1/tokens", &[]);
    client.post_form(&path, params).await
}

#[cfg(feature = "tokens")]
#[doc = "Retrieve a token"]
pub async fn get_token(
    client: &crate::Client,
    token: &str,
    params: &crate::tokens::GetTokenParams,
) -> Result<crate::tokens::Token, crate::Error> {
    let path = crate::params::format_path("/v1/tokens/{token}", &[("token", token)]);
    client.get(&path, params).await
}
